#requires -Version 7.0
<# One-time, idempotent authoritative roadmap amendment. No private Note content is exported. #>
param()
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path -Parent $PSScriptRoot
$token = (Get-Content (Join-Path $repoRoot '.env') -Raw).Trim()
$token = ($token -replace '(?i)^NOTION_(API_)?(TOKEN|KEY|SECRET)\s*=\s*', '').Replace('"', '').Trim()
$headers = @{ Authorization = "Bearer $token"; 'Notion-Version' = '2026-03-11'; 'Content-Type' = 'application/json' }
$title = 'Trustworthy Discovery delivery contract (2026-10-17)'
$product = @(
'This amendment governs automatic topic formation and publication and supersedes earlier three-Note publication minima, anchor-cap termination, and any blanket exclusion based on Non-goals, deferred-work or out-of-scope section headings. Discover meaningful broad and focused subjects without a target or maximum topic count. Preserve independently supported narrow subjects and overlapping Note membership; ungrouped passages and Notes remain valid. Candidate formation, evidence validation, source-supported naming and publication are separate decisions. Withhold uncertain or generic labels while retaining eligible internal candidate evidence and identity. Assess subject distinctness before consolidation; shared members alone never justify merging.',
'Established topics have relevant body evidence from at least two distinct eligible cached Notes. Emerging topics are validated subjects with relevant body evidence from exactly one eligible cached Note; publish them in a separately labelled Emerging topics collection. Apply the same specific source-supported subject and body-evidence requirements, with literal label support from the single Note sufficient for emerging publication. A heading alone, generic keyword collocation or title-family prefix is insufficient. Promotion or demotion between these collections preserves identity when surviving evidence supports continuity. The status is independent of saved interests and candidate identity.',
'A substantive discussion of a non-goal or deferred capability may support a subject about that discussion; it never proves the capability exists. Reject unsupported capability assertions and reference-only evidence, rather than excluding all prose under a heading. Named references remain distinct from Similar passages and cannot alone establish an independent thematic relationship. Preserve current explicit full-unique-title citation rules and literal passage provenance.',
'Every eligible section eventually receives candidate opportunity and evidence evaluation. Resource bounds limit a work slice, never silently truncate the source or declare a capacity-limited sweep complete. Persist versioned resumable progress tied to current source/model/policy/reset identity. Cancellation, backgrounding, playback, memory pressure and budget exhaustion pause work honestly; resume from durable progress on eligibility. Report processed versus eligible sections and partial status. Preserve the prior valid published generation on failed writes or cancellation. Keep orchestration process-scoped, no persistent indexing service, and preserve the existing private derived-storage budget and source-removal rules.',
'Following either an established or emerging topic opens the existing name and editable matching-text confirmation. Save creates an independent explicit interest; Cancel changes nothing. Existing follows open that interest. Removal through Your interests removes the saved interest, not the discovered subject. Renaming, split, merge, promotion, demotion or source loss never silently changes or deletes confirmed matching text. Background work offers explicit Refresh for an inspected generation; mandatory eligibility removals are immediate. Only explicit Play creates or replaces the listening session.',
'Quality acceptance is independent of topic count and recommendation retrieval. Freeze calibration and held-out partitions by Note family before tuning. Record actual human judgments, provisional annotations and unrated cases separately; no unreviewed candidate or topic count is quality evidence. On at least twenty independently human-reviewed held-out subjects and fifty membership judgments, require false publication at most ten percent, missed-subject recall at least eighty percent, membership precision at least ninety percent and useful specific source-supported labels at least eighty percent. Include emerging, overlap, duplicate, misleading-label, missed-subject and reference-only cases. Report denominators and errors; insufficient judgments leave acceptance unmeasured. Existing recommendation precision at least eighty percent, held-out Recall@5 at least eighty percent and warm-query p95 below two seconds at ten thousand passages remain separate binding gates.',
'Before enabling the replacement engine, measure shipping Android processing of ten thousand passages across more than two thousand sections, including uneven section sizes: complete eligible coverage within one hundred twenty seconds of active processing and peak additional Java plus native memory at most one hundred twenty-eight MiB over the idle model-loaded baseline. Pause/cancellation must be observed within one second and durable resume must eventually complete without missing sections. Derived storage remains within sixty-four MiB. Measure cold/warm runtime, process/native/Java peaks, storage and scheduling with playback. Bulk work must pause during playback under the existing scheduling contract; require no new playback errors, skips or session changes attributable to discovery. Report device/API and repeated observations; host timings do not qualify. Human TalkBack speech/listening acceptance remains separate and pending until observed. MiniLM and the experimental flag remain; failed or unmeasured gates block default enablement.'
)
$ui = @(
'This amendment extends the semantic Discovery screen with separate Topics in your Notes and Emerging topics collections. Established topics have at least two distinct supporting Notes; validated single-Note subjects appear only under Emerging topics. Both use the existing compact topic row, passage-backed details, Preview listening and Follow topic confirmation flow. Expose one-Note counts honestly and preserve stable topic-ID navigation and focus when a subject moves between collections after Refresh.',
'Follow topic proposes the source-supported name and editable matching text, saves only on confirmation, and opens an existing interest instead of duplicating it. Removing a follow uses the existing Your interests editing/removal flow. Show incomplete processing with processed and eligible section counts and a pause or recovery explanation, never a complete empty-state claim when candidate coverage is unfinished. Preserve inspected ordering, labels, evidence and focus until explicit Refresh except immediate mandatory source removals. No automatic processing, navigation, Follow or preview action changes playback; only explicit Play does.',
'No fixed topic-count target or publication cap is a product goal. Allow supported broad, focused and overlapping subjects to remain separately reachable. Non-goal or deferred-work discussions may be subjects without implying an implemented capability. Reference-only material does not establish a thematic topic. Apply the Product contract quality and physical Android acceptance gates before enabling the replacement engine; semantic tests cannot substitute for human TalkBack speech/listening acceptance.'
)
$integration = @(
'The Trustworthy Discovery delivery amendment in the Product and UI contracts governs the replacement engine. Complete eligible-section opportunity through bounded cancellable resumable work; do not use a section cap as terminal completion. Persist progress tied to source/model/policy/reset identity with accurate incomplete coverage. Resource pressure pauses work rather than silently discarding remaining sections. Preserve prior valid generations on rejected writes and cancellation, current source eligibility checks and the sixty-four MiB derived budget.',
'Publication status distinguishes established subjects with at least two distinct supporting Notes from validated single-Note Emerging topics without changing independent saved interests. Literal body evidence and specific subject labels remain required. Substantive discussion under non-goal/deferred headings is eligible without claiming that a capability exists. Existing reference classification, source-removal/privacy rules, exact search, process-scoped worker and playback/background scheduling remain binding. No whole passage-pair matrix, Python runtime, cloud inference or new model is introduced. The experimental flag stays disabled until the governing human-quality and physical Android gates pass.'
)
foreach ($entry in @(
    @{ Id = '3dec9345-e10a-81ab-aa68-cf0b2ee17e45'; Text = $product },
    @{ Id = '3dec9345-e10a-81b6-9cd2-d54532ad6fcd'; Text = $ui },
    @{ Id = '3dec9345-e10a-81e8-8b28-e7d04672e53e'; Text = $integration }
)) {
    # Read the complete current top-level text before an idempotent append. Never patch the model code block.
    $existing = @(); $cursor = $null
    do {
        $uri = "https://api.notion.com/v1/blocks/$($entry.Id)/children?page_size=100"
        if ($cursor) { $uri += "&start_cursor=$cursor" }
        $response = Invoke-RestMethod -Uri $uri -Headers $headers
        $existing += $response.results; $cursor = $response.next_cursor
    } while ($response.has_more)
    if ($existing | Where-Object { $_.type -eq 'heading_1' -and (($_.heading_1.rich_text | ForEach-Object plain_text) -join '') -in @($title, 'Automatic topics: formation, publication and acceptance') }) {
        Write-Output "Already amended $($entry.Id)"; continue
    }
    $children = @(@{ object = 'block'; type = 'heading_1'; heading_1 = @{ rich_text = @(@{ type = 'text'; text = @{ content = $title } }) } })
    foreach ($paragraph in $entry.Text) {
        if ($paragraph.Length -gt 2000) { throw 'Notion rich-text length exceeded' }
        $children += @{ object = 'block'; type = 'paragraph'; paragraph = @{ rich_text = @(@{ type = 'text'; text = @{ content = $paragraph } }) } }
    }
    $body = @{ children = $children } | ConvertTo-Json -Depth 12 -Compress
    $null = Invoke-RestMethod -Method Patch -Uri "https://api.notion.com/v1/blocks/$($entry.Id)/children" -Headers $headers -Body ([System.Text.Encoding]::UTF8.GetBytes($body))
    Write-Output "Amended $($entry.Id)"
}
